import { edit_and_get_delete_resource } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import trashIcon from "@/assets/trash.png";
export default {
  props: {
    activeDeactiveDialog: Boolean,
    rowData: Object
  },
  data() {
    return {
      loading: false,
      trashIcon: trashIcon
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async active_deactive_actions() {
      this.loading = true;
      try {
        var data = this.$store.getters.GetUserObj;
        if (!data || !data.organization) {
          throw new Error("User data not available");
        }
        let result = await API.graphql(graphqlOperation(edit_and_get_delete_resource, {
          input: {
            action_type: "DELETE_ACTIAVTE",
            organization_id: data.organization.organization_id,
            resource_id: this.rowData.resource_id,
            resource_status: this.rowData.resource_status == "ACTIVE" ? "DEACTIVE" : "ACTIVE"
          }
        }));
        var response = JSON.parse(result.data.edit_and_get_delete_resource);
        if (response.Status == "SUCCESS") {
          this.$emit("SuccessMsg", response.Message);
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message || "Failed to update resource status");
        }
      } catch (error) {
        console.error("Error updating resource status:", error);
        const errorMessage = error.errors && error.errors[0] ? error.errors[0].message : "Failed to update resource status. Please try again.";
        this.$emit("errorMsg", errorMessage);
      } finally {
        this.loading = false;
      }
    }
  }
};
